/* deterministic pseudo-noise (xorshift, sum of four uniforms), so every render draws the same trace */
const CM_noise=(n,seed)=>{let s=seed|0;const r=()=>{s^=s<<13;s^=s>>>17;s^=s<<5;return (s>>>0)/4294967296};const o=[];for(let i=0;i<n;i++)o.push((r()+r()+r()+r()-2)*Math.sqrt(3));return o};
