/* the hook: a 7-chip code hidden in noise, and its correlation with the stored code (computed here, not drawn by hand) */
const CM_CODE=[1,1,1,-1,-1,1,-1], CM_CH=8, CM_N=200, CM_AT=84;
const CM_RX=(()=>{const w=CM_noise(CM_N,20261121);return w.map((v,i)=>{const j=Math.floor((i-CM_AT)/CM_CH);return 0.6*(i>=CM_AT&&j<7?CM_CODE[j]:0)+0.6*v})})();
const CM_COR=(()=>{const L=7*CM_CH,o=[];for(let i=0;i<=CM_N-L;i++){let z=0;for(let k=0;k<L;k++)z+=CM_RX[i+k]*CM_CODE[Math.floor(k/CM_CH)];o.push(z)}return o})();
